import {rotateSceneryBlock} from './scenery-block-rotation.js';
import {blockCanvas,extractBlock,isBlock,openBlock} from './core/blocks.js';
import {generateMap} from './core/maps.js';
import {DIRECTIONS,CONNECTION_TYPES} from './core/connections.js';
import {emptyFeaturePlan,seededFeaturePlan} from './core/feature-plan.js';
import {generateConnectedMap} from './editor-3d-generator.js';
import {listDesigns,getDesign,saveDesign} from './editor-3d-store.js';

export function installLibrary({getDocument,run,open,guardReplace,refreshSaves,status,switchWorkspace}){
 const $=id=>document.getElementById(id),host=document.createElement('section');
 host.innerHTML=`<h2>Blocks & generation</h2><label>Workspace<select id="workspace"><option value="map">Sector / local map · 240 × 240</option><option value="block">Reusable block · 24 × 24</option></select></label><button id="new-block">New block</button><button id="rotate-scenery-block">Rotate scenery block 90°</button><p class="muted">Map and block workspaces retain their edits and undo history. Save designs to keep them after closing.</p><div class="row"><button id="capture-block">Save selected block</button><button id="place-block">Place selected block</button></div><p class="muted">Capture and place use the block column and row above. Placement replaces that block on every authored layer.</p><details><summary>Block connections</summary><div id="block-connections"></div><button id="apply-connections">Apply connections</button><p class="muted">Connections describe existing edges; they do not paint roads or walls. Save connected blocks for the generator.</p></details><details><summary>Generate a map</summary><label>Seed<input id="generation-seed" type="number" min="0" max="4294967295" value="7"></label><label>Layout<select id="generation-layout"><option value="factory">Factory</option><option value="river-ns">River north–south</option><option value="river-ew">River east–west</option></select></label><button id="generate-map">Generate layout</button><button id="generate-connected">Generate from saved blocks</button><p class="muted">Generation replaces the full map in one undo step. Connected generation uses saved blocks with all four connections assigned.</p><details><summary>Feature plan · rows and columns</summary><div id="generation-plan"></div><div class="row"><button id="seed-plan">Seed road / fence</button><button id="clear-plan">Clear plan</button></div><button id="apply-plan">Apply feature plan</button></details></details>`;
 document.querySelector('.tools').append(host);
 const select=(id,label)=>{const l=document.createElement('label');l.textContent=label;const s=document.createElement('select');s.id=id;for(const t of CONNECTION_TYPES)s.add(new Option(t,t));l.append(s);return l;};
 for(const d of DIRECTIONS)$('block-connections').append(select('connection-'+d,d));
 for(let i=0;i<10;i++){const row=document.createElement('div');row.className='row';for(const axis of ['rows','columns'])row.append(select('plan-'+axis+'-'+i,(axis==='rows'?'Row ':'Column ')+(i+1)));$('generation-plan').append(row);}
 const seed=()=>{const n=Number($('generation-seed').value);if(!Number.isInteger(n)||n<0||n>4294967295)throw Error('Use a whole-number seed from 0 to 4294967295.');return n;};
 const sector=()=>[Number($('sector-x').value)-1,Number($('sector-y').value)-1];
 const plan=()=>({version:1,...Object.fromEntries(['rows','columns'].map(axis=>[axis,Array.from({length:10},(_,i)=>$('plan-'+axis+'-'+i).value)]))});
 const mapOnly=()=>{if(getDocument().block)throw Error('Switch to the full map workspace.');};
 $('workspace').onchange=()=>switchWorkspace($('workspace').value);
 $('new-block').onclick=async()=>{if(!guardReplace())return;try{await open(JSON.stringify(extractBlock(blockCanvas('New block'))));}catch(e){status(e.message);}};
 $('rotate-scenery-block').onclick=()=>run(()=>{const d=getDocument();if(!d.block)throw Error('Open a reusable scenery block first.');d.replace(openBlock(rotateSceneryBlock(d.capture(0,0))));},'Scenery block rotated. Undo restores it.');
 $('capture-block').onclick=()=>run(async()=>{const d=getDocument().capture(...sector());d.name=(getDocument().map.name+' block '+sector().map(n=>n+1).join(',')).slice(0,60);const id=crypto.randomUUID();await saveDesign({id,name:d.name,json:JSON.stringify(d),updated:Date.now(),version:1});await refreshSaves();$('saved-designs').value=id;},'Selected block saved to the library.',false);
 $('place-block').onclick=()=>run(async()=>{mapOnly();const row=await getDesign($('saved-designs').value);if(!row)throw Error('Select a saved block from the Design library.');const d=JSON.parse(row.json);if(!isBlock(d))throw Error('Choose a block, not a full map.');getDocument().place(d,...sector());},'Block placed. Undo restores the block.');
 $('apply-connections').onclick=()=>run(()=>getDocument().connections(Object.fromEntries(DIRECTIONS.map(d=>[d,$('connection-'+d).value]))),'Connections assigned. Save the block for generation.');
 $('generate-map').onclick=()=>run(()=>{mapOnly();const n=seed(),layout=$('generation-layout').value;getDocument().replace(generateMap(n,'Generated '+n,46,{layout:layout==='factory'?'factory':'river',orientation:layout.endsWith('ew')?'ew':'ns'}));},'Map generated. Undo restores the previous design.');
 $('generate-connected').onclick=()=>run(async()=>{mapOnly();const rows=await listDesigns(),blocks=rows.map(r=>JSON.parse(r.json)).filter(d=>isBlock(d)&&d.connections);getDocument().replace(generateConnectedMap(blocks,seed(),getDocument().map.generationPlan||getDocument().map.featurePlan||emptyFeaturePlan()));},'Generated 100 matching blocks. Undo restores the previous design.');
 const setPlan=p=>run(()=>{mapOnly();getDocument().replace({...getDocument().editor.map,generationPlan:p()});},'Feature plan updated. Save matching blocks before generating.');
 $('apply-plan').onclick=()=>setPlan(plan);$('seed-plan').onclick=()=>setPlan(()=>seededFeaturePlan(seed()));$('clear-plan').onclick=()=>setPlan(emptyFeaturePlan);
 return {sync(){const d=getDocument();if(!d)return;$('workspace').value=d.block?'block':'map';for(const id of ['capture-block','place-block','generate-map','generate-connected','apply-plan','seed-plan','clear-plan'])$(id).disabled=d.block;$('apply-connections').disabled=!d.block;$('rotate-scenery-block').disabled=!d.block;for(const dir of DIRECTIONS){$('connection-'+dir).disabled=!d.block;$('connection-'+dir).value=d.editor.map.blockConnections?.['0,0']?.[dir]||'none';}const p=d.map.generationPlan||d.map.featurePlan||emptyFeaturePlan();for(const axis of ['rows','columns'])for(let i=0;i<10;i++){$('plan-'+axis+'-'+i).value=p[axis][i];$('plan-'+axis+'-'+i).disabled=d.block;}}};
}
